  "command": "replace_content_by_matching",
  "args": {
    "old_content": "module TopModule (
    input  logic       clk,
    input  logic       reset,
    output logic [3:0] q
);

    // Counter register: must represent 1..10
    logic [3:0] count;

    // Initialize to a known value to avoid X before the first synchronous reset
    initial begin
        count = 4'd1;
    end

    // Synchronous decade counter (counts 1..10 inclusive)
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd1;
        end else begin
            if (count == 4'd10)
                count <= 4'd1;
            else
                count <= count + 4'd1;
        end
    end

    assign q = count;

endmodule
",
